const app=document.querySelector('#app');
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const json=x=>esc(JSON.stringify(x,null,2));
const api=async(path,body)=>{const r=await fetch('/v0/'+path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});return {status:r.status,data:await r.json()}};
const node=(label,body,cls='')=>`<section class="node ${cls}"><span class="stage">${label}</span>${body}</section>`;
const offchain=`<aside class="aside"><strong>fvapi: untrusted search</strong><p>The server finds a candidate. Its answer is not part of your trusted base.</p><p>Solid links show what you can check. They do not mean that this browser has checked it.</p></aside>`;
const guard=async action=>{try{await action()}catch(error){document.querySelector('#result').innerHTML=node('Connection · broken link',`<h2>The request did not complete.</h2><p>${esc(error.message)}</p><p>Check the API connection and try again.</p>`,'broken')}};
const intro=(title,subtitle)=>`<div class="intro"><div><h1>${title}</h1><p>${subtitle}</p></div>${offchain}</div>`;
const replayStatus=e=>e.replay?.status??e.replay_status;
function entryChain(e){const recorded=replayStatus(e)==='recorded';return `<div class="chain">${node('Claim · you match it',`<h2>${esc(e.title)}</h2><p>${esc(e.claim)}</p><span class="kind">${esc(e.id)} / ${esc(e.kind)}</span>`)}${node('Statement · you read it',e.statements?.map(s=>`<h3>${esc(s.name)}</h3><p class="muted">${esc(s.file)}:${esc(s.line)}</p><pre>${esc(s.text)}</pre>`).join('')||'<p>Statement files are not available in this summary. Open a full entry before you rely on it.</p>')}${node('Closure · you hash it',e.closure?.map(f=>`<div class="file"><strong>${esc(f.path)}</strong><code>SHA-256 ${esc(f.sha256)}</code><span class="muted">${esc(f.bytes)} bytes</span></div>`).join('')||'<p>The summary does not include closure hashes.</p>')}${node(recorded?'Replay · broken link':'Replay · you run it',`<h2>${recorded?'RECORDED — not re-run by fvapi':'Run the proof yourself'}</h2><p>${recorded?'This transcript is from an earlier run. It is not evidence of a new replay.':'The API marks this replay as real. Download the files and run it locally; this browser does not run Lean.'}</p>${e.replay?`<pre id="replay-command">${esc(e.replay.command)}</pre><button class="secondary" id="copy-command">Copy replay command</button><p class="muted" id="copy-status"></p><p>${esc(e.replay.note)}</p>${e.replay.transcript?`<details><summary>Recorded transcript</summary><pre>${esc(e.replay.transcript)}</pre></details>`:''}`:''}`,recorded?'broken':'')}${node('Axioms · you accept these',e.replay?`<p>Check that the replay uses only the expected axioms.</p><pre>${esc(e.replay.expect_axioms.join('\n'))}</pre>`:'<p>Expected axioms are unavailable in this summary.</p>')}${node('Trusted base · you choose it',`<h2>Lean kernel + toolchain</h2><code>${esc(e.toolchain)}</code><p class="muted">Dependencies: ${esc(e.requires?.join(', ')||'not included in summary')}</p>`,'base')}${e.source?node('Provenance + permission',`<h3>Source</h3><p>${esc(e.source.repo)}<br>Commit <code>${esc(e.source.commit)}</code></p><pre>${esc(e.source.paths.join('\n'))}</pre><h3>Licence</h3><p>${esc(e.licence.spdx)}</p><h3>Third-party notices</h3>${e.licence.third_party.length?e.licence.third_party.map(t=>`<p>${esc(t.name)}: ${esc(t.spdx)}<br>${esc(t.source)}</p>`).join(''):'<p>No third-party notices listed by this entry.</p>'}`):''}</div>`}
async function catalog(){const {data}=await api('catalog');app.innerHTML=intro('What can you check?','Follow a claim down to its trusted base. A missing link stays visible.')+`<div class="legend"><span>Caller-checkable link</span><span>Recorded or unavailable link</span></div><div class="catalog">${data.entries.map(e=>`<article class="catalog-item mini"><span class="kind">${esc(e.kind)}</span><h2><a href="#entry/${encodeURIComponent(e.id)}">${esc(e.title)}</a></h2>${node('Claim',`<p>${esc(e.claim)}</p>`)}${node('Replay',`<strong>${replayStatus(e)==='recorded'?'RECORDED':'Runnable proof'}</strong><p>${replayStatus(e)==='recorded'?'Not re-run by fvapi.':'Read, hash, then replay locally.'}</p>`,replayStatus(e)==='recorded'?'broken':'')}${node('Trusted base',`<code>${esc(e.toolchain)}</code>`,'base')}</article>`).join('')}</div>`}
async function entry(id){const r=await api('catalog/'+encodeURIComponent(id));let e=r.data;if(r.status===404){const c=await api('catalog');e=c.data.entries.find(x=>x.id===id);if(!e)throw Error('The entry was not found. Return to the catalog.')}app.innerHTML=intro('Inspect the chain','Read the statement before you trust the result.')+`<div class="actions"><a class="button secondary" href="/v0/bundles/${encodeURIComponent(e.id)}.tar.gz">Download bundle</a><a class="button secondary" href="#check/${encodeURIComponent(e.id)}">Run check</a></div><p class="muted">Bundle delivery depends on the API. The fixture mock does not serve archives.</p><div class="chain-layout">${entryChain(e)}<aside class="aside"><strong>Your decision boundary</strong><p>The statement must mean what you intend. Hashes protect the supplied bytes, not their meaning.</p><p>A recorded replay leaves this chain incomplete until you run it.</p></aside></div>`;bindCopy()}
function bindCopy(){document.querySelector('#copy-command')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(document.querySelector('#replay-command').textContent);document.querySelector('#copy-status').textContent='Replay command copied.'}catch{document.querySelector('#copy-status').textContent='Clipboard access failed. Select and copy the command above.'}})}
async function lookup(state){app.innerHTML=intro('Find a claim','The search result starts a chain. It does not complete one.')+`<form id="lookup" class="form"><label for="query-type">Match by</label><select id="query-type"><option value="spec_id">Entry ID</option><option value="artifact_sha256">Artifact SHA-256</option><option value="statement">Statement text</option></select><label for="query">Value</label><input id="query" value="${state==='lookup-miss'?'not-in-library':'vf.contrast-2x2'}" required><div class="actions"><button>Look up</button></div></form><div id="result"></div>`;const form=document.querySelector('#lookup');form.onsubmit=event=>{event.preventDefault();return guard(async()=>{const {status,data}=await api('lookup',{[document.querySelector('#query-type').value]:document.querySelector('#query').value});document.querySelector('#result').innerHTML=status===404?node('Search · no claim link',`<h2>No match. Logged as demand.</h2><p>The library has no answer to this query. Change the value to try again, or inspect the demand log.</p><pre>${json(data)}</pre><a href="#demand">Open demand log</a>`,'broken'):status!==200?node('Search failed',`<p>${esc(data.detail)}. Change the query and try again.</p>`,'broken'):`<p class="tag">Match found on ${esc(data.matched_on)}</p>${entryChain(data.entry)}`;bindCopy()})};if(state!=='lookup')await form.onsubmit({preventDefault(){}})}
async function checks(state,id='vf.contrast-2x2'){const catalogData=(await api('catalog')).data;const checker=(await api('catalog/vf.contrast-2x2')).data;let input=structuredClone(checker.check.example_input);if(state==='check-reject')input.rows[0].weights[0]+=1;if(state==='check-409')id=catalogData.entries.find(e=>e.kind!=='checker').id;app.innerHTML=intro('Check an input','A server verdict is a lead. Re-run the same input from the bundle.')+`<form id="check-form" class="form"><label for="check-id">Entry</label><select id="check-id">${catalogData.entries.map(e=>`<option value="${esc(e.id)}" ${e.id===id?'selected':''}>${esc(e.id)}${e.kind==='checker'?'':' (no checker)'}</option>`).join('')}</select><label for="check-input">Input JSON — edit the weights to test a rejection</label><textarea id="check-input" spellcheck="false">${json(input)}</textarea><div class="actions"><button>Run check</button><button class="secondary" type="button" id="reset">Use example input</button></div></form><div id="result"></div>`;document.querySelector('#reset').onclick=()=>document.querySelector('#check-input').value=JSON.stringify(checker.check.example_input,null,2);const form=document.querySelector('#check-form');form.onsubmit=event=>{event.preventDefault();return guard(async()=>{const target=document.querySelector('#result');let body;try{body=JSON.parse(document.querySelector('#check-input').value)}catch{target.innerHTML=node('Input · broken link','<h2>Input is not valid JSON.</h2><p>Correct the JSON syntax and run the check again.</p>','broken');return}const r=await api('checks/'+encodeURIComponent(document.querySelector('#check-id').value),body);target.innerHTML=r.status!==200?node('Checker · unavailable',`<h2>${r.status===409?'409 — This entry has no runnable checker.':'The check failed.'}</h2><p>Select a checker entry and run the check again.</p><pre>${json(r.data)}</pre>`,'broken'):node('Server verdict · outside the trusted base',`<h2>${r.data.verdict==='accept'?'Accepted by the server':'Rejected by the server'}</h2><p>Exit code ${esc(r.data.exit_code)}. Ran on ${esc(r.data.ran_on)} in ${esc(r.data.elapsed_ms)} ms.</p><pre>${json(r.data.output)}</pre>`,r.data.verdict==='reject'?'broken':'')+node('Replay · you recheck',`<p>Save the same JSON as input.json. Fetch the bundle and run:</p><pre>${esc(r.data.recheck.command)}</pre><p>The browser has not rechecked this verdict.</p>`)+node('Trusted base','<h2>Local checker + Lean kernel</h2><p>Inspect the entry chain before you rely on the result.</p><a style="color:white" href="#entry/vf.contrast-2x2">Inspect the proof chain</a>','base');if(state.startsWith('check-'))target.scrollIntoView({block:'start'})})};if(state.startsWith('check-'))await form.onsubmit({preventDefault(){}})}
async function logs(kind){const {data}=await api(kind);app.innerHTML=intro(kind==='demand'?'Where the chain stops':'What the server returned',kind==='demand'?'Unanswered requests become library demand, not invented answers.':'Answers record server activity. They do not certify a local replay.')+(kind==='demand'?`<h2>Demand by key</h2>${data.by_key.map(k=>`<div class="summary"><span class="count">${esc(k.count)}</span><code>${esc(k.key)}</code></div>`).join('')}<h2>Misses</h2>`:'')+(kind==='demand'?data.misses:data.answers).map(row=>`<article class="log-row"><div><strong>${esc(row.miss_id||row.answer_id)}</strong><p class="muted">${esc(row.at)}</p></div><div class="log-path ${kind==='demand'?'broken':''}"><h3>${kind==='demand'?'Request → no library match':`${esc(row.kind)} → ${esc(row.verdict||'candidate found')}`}</h3>${row.query?`<pre>${json(row.query)}</pre><p>Logged as demand. No proof chain was returned.</p>`:`<a href="#entry/${encodeURIComponent(row.entry_id)}">${esc(row.entry_id)}</a><p>Open the entry to inspect the checkable chain.</p>`}</div></article>`).join('')||'<p>No requests yet. Run a lookup to start.</p>'}
async function route(){app.removeAttribute('data-ready');const [state='catalog',id]=location.hash.slice(1).split('/');document.querySelectorAll('nav a').forEach(a=>a.toggleAttribute('aria-current',a.hash==='#'+state));try{if(state==='catalog'||!state)await catalog();else if(state==='entry')await entry(decodeURIComponent(id));else if(state==='recorded')await entry('fva.glm-iround');else if(state.startsWith('lookup'))await lookup(state);else if(state.startsWith('check'))await checks(state,id?decodeURIComponent(id):undefined);else if(state==='demand'||state==='answers')await logs(state);else await catalog();app.dataset.ready='true'}catch(error){app.innerHTML=node('Connection · broken link',`<h1>Cannot load the chain.</h1><p>${esc(error.message)}</p><p>Check the API connection and reload this page.</p>`,'broken');app.dataset.ready='error'}}
window.addEventListener('hashchange',route);route();
